    if (isHeightAspectGuideCheckboxHit) {
      this.#isHeightAspectGuideVisible = !this.#isHeightAspectGuideVisible;
      this.saveSettings();
      return;
    }
    const widthAspectGuideRowY = panelY + ITEM_HEIGHT * 4;
